if !(IsFeatureImplemented(FEAT_OCCMO) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif EffectivelyAtEL0NotInHost() then
    if SCTLR_EL1().UCI == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EL2Enabled() && HCR_EL2().TPCP == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HFGITR_EL2().DCCVAC == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        AArch64_DC(X{64}(t), CacheType_Data, CacheOp_Clean, CacheOpScope_OuterCache);
    end;
elsif EffectivelyAtEL0InHost() then
    if SCTLR_EL2().UCI == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        AArch64_DC(X{64}(t), CacheType_Data, CacheOp_Clean, CacheOpScope_OuterCache);
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && HCR_EL2().TPCP == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HFGITR_EL2().DCCVAC == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        AArch64_DC(X{64}(t), CacheType_Data, CacheOp_Clean, CacheOpScope_OuterCache);
    end;
elsif PSTATE.EL == EL2 then
    AArch64_DC(X{64}(t), CacheType_Data, CacheOp_Clean, CacheOpScope_OuterCache);
elsif PSTATE.EL == EL3 then
    AArch64_DC(X{64}(t), CacheType_Data, CacheOp_Clean, CacheOpScope_OuterCache);
end;
